insert  into `template`(`id`,`title`,`content`,`prefix`,`suffix`,`file_type`,`module_name`,`crt_time`,`upt_time`) values ('1511296643851489280','dao','package ${packageSpace}.${moduleName};\n\nimport ${packageSpace}.pojo.entity.${className}Entity;\nimport com.yulinlin.repository.anno.JoinRepository;\nimport com.yulinlin.repository.dao.BaseRepository;\n\n@JoinRepository\npublic interface ${prefix}${className}${suffix} extends BaseRepository<${className}Entity>  {\n\n\n\n}\n','','Dao','java','dao','2022-04-05 18:56:13','2022-04-05 18:56:13'),('1511297429801144320','entity','package ${packageSpace}.${moduleName};\n\nimport com.yulinlin.common.domain.SuperEntity;\n\nimport com.yulinlin.data.core.anno.*;\nimport io.swagger.annotations.ApiModel;\nimport io.swagger.annotations.ApiModelProperty;\nimport lombok.Data;\n\nimport javax.validation.constraints.NotEmpty;\nimport java.util.Date;\n\n\n\n@Data\n@ApiModel(\"${tableComment}\")\n@JoinTable(\"${tableName}\")\npublic class ${prefix}${className}${suffix} extends SuperEntity<${prefix}${className}${suffix}>  {\n\n\n\n<#list columnList as column>\n\n        <#if column.getFieldName() == \'id\'>\n\n        <#elseif column.getFieldName() == \'crtTime\'>\n\n        <#elseif column.getFieldName() == \'uptTime\'>\n\n        <#else >\n        @NotEmpty(message = \"必填\")\n        @ApiModelProperty(\"${column.columnComment}\")\n        @JoinWhere\n        @JoinField\n        private ${column.getFieldType()} ${column.getFieldName()};\n        </#if>\n</#list>\n\n\n}\n','','Entity','java','pojo.entity','2022-04-05 18:59:20','2022-04-05 18:59:20'),('1511298053158604800','service','package ${packageSpace}.${moduleName};\n\nimport ${packageSpace}.pojo.entity.${className}Entity;\n\nimport com.yulinlin.common.service.*;\n\n\npublic interface ${prefix}${className}${suffix} extends ISuperService<${className}Entity>  {\n\n\n\n}\n\n','I','Service','java','service','2022-04-05 19:01:49','2022-04-05 19:01:49'),('1511298174931832832','ServiceImpl','package ${packageSpace}.${moduleName};\n\nimport ${packageSpace}.service.I${className}Service;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.stereotype.Service;\nimport org.springframework.transaction.annotation.Transactional;\nimport ${packageSpace}.pojo.entity.${className}Entity;\nimport ${packageSpace}.dao.${className}Dao;\nimport com.yulinlin.common.service.impl2.ServiceImpl;\n\n@Service\n@Transactional\npublic class ${prefix}${className}${suffix} extends ServiceImpl<${className}Entity> implements I${className}Service  {\n\n\n    @Autowired\n    private ${className}Dao repository;\n\n}\n','','ServiceImpl','java','service.impl','2022-04-05 19:02:18','2022-04-05 19:02:18'),('1511298285313331200','controller','package ${packageSpace}.${moduleName};\n\nimport ${packageSpace}.pojo.entity.${className}Entity;\nimport ${packageSpace}.pojo.page.${className}Page;\nimport ${packageSpace}.pojo.config.${className}Config;\n\nimport com.yulinlin.common.controller.SuperController;\nimport com.yulinlin.starter.domain.ResponseVo;\nimport io.swagger.annotations.Api;\nimport io.swagger.annotations.ApiOperation;\nimport org.springframework.web.bind.annotation.RequestMapping;\nimport org.springframework.web.bind.annotation.RequestMethod;\nimport org.springframework.web.bind.annotation.RestController;\n\n@Api(tags = \"${tableComment}\")\n@RestController\n@RequestMapping(\"${className?uncap_first}\")\npublic class ${prefix}${className}${suffix} extends SuperController<${className}Entity,${className}Page>  {\n\n\n    @ApiOperation(\"获取配置数据\")\n    @RequestMapping(value = \"config\",method = RequestMethod.POST)\n    public ResponseVo<${className}Config> config() {\n        ${className}Config config =${className}Config.newInstance();\n        return ResponseVo.newInstance(config);\n    }\n\n\n}','','Controller','java','controller','2022-04-05 19:02:44','2022-04-05 19:02:44'),('1511298355052023808','page','package ${packageSpace}.${moduleName};\n\nimport com.yulinlin.common.domain.po.PagePo;\nimport lombok.Data;\n\n@Data\npublic class ${prefix}${className}${suffix} extends PagePo {\n\n\n}\n','','Page','java','pojo.page','2022-04-05 19:03:01','2022-04-05 19:03:01'),('1511298448597585920','enums','package ${packageSpace}.${moduleName};\n\npublic class ${prefix}${className}${suffix}  {\n\n\n\n\n}\n','','Enums','java','pojo.enums','2022-04-05 19:03:23','2022-04-05 19:03:23'),('1511409994187280384','vue','<template>\n    <div class=\"app-container\">\n        <el-form :inline=\"true\" :model=\"queryForm\">\n\n        <#list columnList as column>\n\n            <#if column.getFieldName() == \'id\'>\n\n            <#elseif column.getFieldName() == \'crtTime\'>\n\n            <#elseif column.getFieldName() == \'uptTime\'>\n\n            <#else >\n\n            <el-form-item prop=\"${column.getFieldName()}\" label=\"${column.columnComment}\">\n                <el-input v-model=\"queryForm.${column.getFieldName()}\"></el-input>\n            </el-form-item>\n            </#if>\n        </#list>\n\n\n        </el-form>\n\n        <div class=\"l_right\">\n            <el-button @click=\"onSearch\" class=\"l_button\" type=\"primary\" size=\"small\">\n                查询\n            </el-button>\n            <el-button\n                    @click=\"onStartSave({})\"\n                    class=\"l_button\"\n                    type=\"success\"\n                    size=\"small\"\n            >\n                添加\n            </el-button>\n            <el-button\n                    @click=\"onNextSave\"\n                    :disabled=\"selectRows.length == 0\"\n                    class=\"l_button\"\n                    type=\"info\"\n                    size=\"small\"\n            >\n                批量编辑\n            </el-button>\n            <el-button\n                    @click=\"onDeleteByIdIn\"\n                    :disabled=\"selectRows.length == 0\"\n                    class=\"l_button\"\n                    type=\"warning\"\n                    size=\"small\"\n            >\n                批量删除\n            </el-button>\n        </div>\n\n        <el-table\n                :data=\"list\"\n                border\n                stripe\n                @sort-change=\"onSortChange\"\n                @selection-change=\"onHandleSelectionChange\"\n                ref=\"dataTable\"\n                style=\"width: 100%\"\n        >\n            <el-table-column\n                    prop=\"selection\"\n                    label=\"多选\"\n                    type=\"selection\"\n                    width=\"60\"\n            >\n            </el-table-column>\n            <el-table-column type=\"index\" label=\"#\" prop=\"index\" width=\"60\">\n            </el-table-column>\n\n        <#list columnList as column>\n\n            <#if column.getFieldName() == \'id\'>\n\n            <#elseif column.getFieldName() == \'crtTime\'>\n\n            <#elseif column.getFieldName() == \'uptTime\'>\n\n            <#else >\n            <el-table-column prop=\"${column.getFieldName()}\" label=\"${column.columnComment}\"> </el-table-column>\n            </#if>\n        </#list>\n\n\n\n\n\n            <el-table-column prop=\"nickname\" label=\"昵称\"> </el-table-column>\n\n            <el-table-column prop=\"crtTime\" label=\"创建时间\" sortable=\"custom\">\n                <template #default=\"{ row }\">\n                    {{ row.crtTime }}\n                </template>\n            </el-table-column>\n\n            <el-table-column label=\"操作\" >\n                <template #default=\"{row}\">\n                    <el-button @click=\"onStartSave(row)\" type=\"primary\" size=\"small\">编辑</el-button>\n                    <el-button @click=\"onDeleteById(row)\" type=\"warning\" size=\"small\">删除</el-button>\n                </template>\n            </el-table-column>\n        </el-table>\n\n        <div class=\"l_page\">\n            <el-pagination\n                    background\n                    @size-change=\"onPage\"\n                    @current-change=\"onPage\"\n                    v-model:current-page=\"pageNumber\"\n                    :page-sizes=\"pageSizes\"\n                    v-model:page-size=\"pageSize\"\n                    layout=\"total, sizes, prev, pager, next, jumper\"\n                    :total=\"total\"\n            >\n            </el-pagination>\n        </div>\n\n        <el-dialog\n                title=\"编辑\"\n                v-model=\"saveDialog\"\n                width=\"700px\"\n                :before-close=\"onHandleClose\"\n        >\n            <div>\n                <el-form\n                        :rules=\"validRule\"\n                        ref=\"saveForm\"\n                        label-position=\"left\"\n                        label-width=\"80px\"\n                        :model=\"saveForm\"\n                >\n\n                <#list columnList as column>\n\n                    <#if column.getFieldName() == \'id\'>\n\n                    <#elseif column.getFieldName() == \'crtTime\'>\n\n                    <#elseif column.getFieldName() == \'uptTime\'>\n\n                    <#else >\n\n                    <el-form-item prop=\"${column.getFieldName()}\" label=\"${column.columnComment}\">\n                        <el-input v-model=\"saveForm.${column.getFieldName()}\"></el-input>\n                    </el-form-item>\n                    </#if>\n                </#list>\n\n\n\n\n\n                </el-form>\n            </div>\n            <template #footer class=\"dialog-footer\">\n                <el-button @click=\"onSubmitSave(false)\">取 消</el-button>\n                <el-button type=\"primary\" @click=\"onSubmitSave(true)\">确 定</el-button>\n            </template>\n        </el-dialog>\n    </div>\n</template>\n\n<metrics>\n\n    <#if domain??>\n       import api from \"@/api/${domain}/${className}Api\";\n     <#else >\n       import api from \"@/api/${className}Api\";\n    </#if>\n  \n\n    export default {\n        name:\'${prefix}${className}${suffix}\',\n        data() {\n            return {\n                //修改对话框\n                saveDialog: false,\n\n                //列表数据\n                list: [],\n                //选中的数据\n                selectRows: [],\n\n                total: 0,\n                pageNumber: 1,\n                pageSize: 15,\n                pageSizes: [15, 30, 60, 100, 200, 300],\n                queryForm: {},\n                saveForm: {},\n\n                validRule: {\n\n                <#list columnList as column>\n\n                    <#if column.getFieldName() == \'id\'>\n\n                    <#elseif column.getFieldName() == \'crtTime\'>\n\n                    <#elseif column.getFieldName() == \'uptTime\'>\n\n                    <#else >\n\n                    ${column.getFieldName()}:[\n                        { required: true, message: \'请输入\', trigger: \'blur\' }\n                    ],\n                    </#if>\n                </#list>\n\n\n\n\n        },\n            orderList: [\n                {\n                    name: \"crtTime\",\n                    asc: false,\n                },\n            ],\n        };\n        },\n\n        mounted() {\n            this.init(api);\n        },\n\n        methods: {\n            init() {\n\n                this.onConfig();\n                this.onSearch();\n\n\n            },\n\n            onHandleClose(done) {\n                let size = this.selectRows.length;\n                if (size > 0) {\n                    this.$confirm(\'还有\'+size+\'个数据没修改,确认关闭吗？\')\n                            .then((_) => {\n                        done();\n                    this.$refs.dataTable.clearSelection();\n                })\n                .catch((_) => {});\n                } else {\n                    this.$confirm(`放弃本次修改,确认关闭吗？`)\n                            .then((_) => {\n                        done();\n                    this.$refs.dataTable.clearSelection();\n                })\n                .catch((_) => {});\n                }\n            },\n            onSearch() {\n                this.pageNumber = 1;\n                this.onPage();\n            },\n\n            onDeleteById(row) {\n                this.selectRows.push(row);\n                this.onDeleteByIdIn();\n            },\n            onDeleteByIdIn() {\n                let size = this.selectRows.length;\n                this.$confirm(\'确认删除\'+size+\'条数据?\', \"提示\", {\n                    confirmButtonText: \"确定\",\n                    cancelButtonText: \"取消\",\n                    type: \"warning\",\n                })\n                        .then(async () => {\n                    let ids = this.selectRows.map((v) => v.id);\n\n                await api.deleteByIdIn(ids);\n                this.onPage();\n            })\n            .catch(() => {});\n            },\n            onSortChange({ column, prop, order }) {\n                this.orderList[0] = {\n                    name: prop,\n                    asc: order != \"descending\",\n                };\n\n                this.onPage();\n            },\n\n            async onConfig() {\n        let data = await api.config(this.$route.query);\n\n        for (let key in data) {\n            this[key] = data[key];\n        }\n    },\n    onHandleSelectionChange(rows) {\n        this.selectRows = rows;\n    },\n    async onStartSave(row) {\n        this.selectRows = [row];\n        this.onNextSave();\n    },\n\n\n    async onNextSave() {\n        if (this.selectRows.length == 0) {\n            this.saveDialog = false;\n            this.selectRows = [];\n            this.onPage();\n            return;\n        } else {\n            this.saveDialog = true;\n        }\n\n        let row = this.selectRows.pop();\n        let saveForm = await api.getById({\n            id:row.id || \"-1\"\n        });\n\n        this.saveDialog = true;\n\n        this.saveForm = saveForm;\n    },\n\n\n    async onSubmitSave(submit = true) {\n        if (submit) {\n            let valid = await this.$refs[\"saveForm\"].validate();\n            if (valid) {\n\n                await api.saveOne(this.saveForm);\n            } else {\n                return;\n            }\n        }\n\n        this.onNextSave();\n    },\n    async onPage() {\n        let data = await api.page({\n            pageNumber: this.pageNumber,\n            pageSize: this.pageSize,\n            orderList: this.orderList,\n                ...this.queryForm,\n    });\n        this.list = data.list;\n        this.total = data.total;\n    },\n    },\n    };\n</metrics>\n\n\n\n<style scoped>\n.l_page {\n  text-align: center;\n  margin: 15px 0px;\n}\n\n.l_right {\n  margin: 10px 0px;\n  display: flex;\n  justify-content: flex-end;\n}\n.l_button {\n  width: 100px;\n}\n.l_form_item {\n  width: 49%;\n}\n</style>\n','','','vue','views','2022-04-06 02:26:37','2022-04-06 02:26:37'),('1511410070422949888','api','import {proxy} from \'@/utils/request\';\n\n\nexport default proxy(\'${className?uncap_first}\')','','','js','api','2022-04-06 02:26:56','2022-04-06 02:26:56'),('1513759239213027328','config','package ${packageSpace}.${moduleName};\nimport lombok.Data;\n\n@Data\npublic class ${prefix}${className}${suffix}  {\n\n\n    public static ${prefix}${className}${suffix} newInstance(){\n        return null;\n    }\n\n}\n','','Config','java','pojo.config','2022-04-12 14:01:41','2022-04-12 14:01:41');

